import { disabled, fieldSurface, focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const otpInput = tv({
  slots: {
    root: "flex w-fit flex-wrap items-center gap-2",
    input: [
      fieldSurface,
      // After fieldSurface, so the monospace face wins over its font-sans.
      "text-center font-mono font-bold caret-foreground",
      "data-filled:bg-secondary aria-invalid:data-filled:bg-danger/15",
      focusRing,
      disabled,
    ],
    separator: "h-1 w-3 shrink-0 bg-border",
  },
  variants: {
    size: {
      sm: { input: "size-11 text-lg" },
      md: { input: "size-12 text-xl" },
      lg: { input: "size-14 text-2xl" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type OtpInputVariants = VariantProps<typeof otpInput>;

"use client";

import { OTPField } from "@base-ui/react/otp-field";
import { otpInput, type OtpInputVariants } from "@/lib/beton/recipes/otp-input.recipe";
import { Fragment, useId } from "react";

export interface OtpInputProps
  extends Omit<OTPField.Root.Props, "className" | "children" | "length">, OtpInputVariants {
  className?: string;
  /** Number of characters. */
  length?: number;
  /** Inserts a separator after every `groupSize` characters, e.g. 3 for "123-456". */
  groupSize?: number;
  /** Accessible name for each slot after the first. */
  slotLabel?: (index: number, length: number) => string;
}

/**
 * A one-time code entry split into single-character slots. Supports paste,
 * autofill from SMS and arrow-key navigation. Label it with a `<label htmlFor>`
 * pointing at `id`, with `aria-labelledby`, or with `aria-label`.
 */
export function OtpInput({
  length = 6,
  groupSize,
  size = "md",
  className,
  slotLabel = (index, total) => `Character ${index + 1} of ${total}`,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: OtpInputProps) {
  const styles = otpInput({ size });
  const labelId = useId();
  // Base UI names the first slot only through aria-labelledby, so an
  // aria-label is rendered as a hidden label element and referenced instead.
  const labelledBy = ariaLabelledBy ?? (ariaLabel ? labelId : undefined);

  return (
    <>
      {ariaLabel && !ariaLabelledBy ? (
        <span id={labelId} hidden>
          {ariaLabel}
        </span>
      ) : null}
      <OTPField.Root
        {...props}
        aria-labelledby={labelledBy}
        length={length}
        data-size={size}
        className={styles.root({ class: className })}
      >
        {Array.from({ length }, (_, index) => (
          <Fragment key={index}>
            {groupSize && index > 0 && index % groupSize === 0 ? (
              <OTPField.Separator className={styles.separator()} />
            ) : null}
            <OTPField.Input
              aria-label={index === 0 ? undefined : slotLabel(index, length)}
              aria-labelledby={index === 0 ? labelledBy : undefined}
              className={styles.input()}
            />
          </Fragment>
        ))}
      </OTPField.Root>
    </>
  );
}
